INSERT INTO changelog (title, body, created_at) VALUES ('Ключ доступу Claude — 90 днів', 'Ключ «Доступ для Claude (розробка)» тепер живе 90 днів замість 7. Чинний ключ продовжено автоматично — генерувати новий не треба. Вимкнути доступ можна будь-коли: Налаштування → Доступи → «Вимкнути доступ».', datetime('now'));
